package app.loveu;

import android.content.Context;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.InterruptedIOException;

/** Serialized relay delivery. Only authenticated ciphertext is staged while the UI is closed. */
public final class CoupleBackgroundSync {
 public static final Object LOCK=new Object();
 private static final String SPOOL="backgroundSpool", ENABLED="backgroundDelivery";
 private CoupleBackgroundSync(){}
 public interface Receiver { void receive(JSONObject couple,JSONObject envelope)throws Exception; }
 private interface Mutation { void apply(JSONObject couple)throws Exception; }
 public static boolean enabled(Context context){try{JSONObject c=new Vault(context).read().optJSONObject("couple");return c!=null&&c.optBoolean(ENABLED,false)&&!c.optString("token").isEmpty()&&!c.optString("id").isEmpty()&&!c.optString("publicKey").isEmpty()&&!c.optString("privateKey").isEmpty()&&!c.optString("pairId").isEmpty()&&c.optJSONObject("peer")!=null;}catch(Exception unavailable){return false;}}
 public static void setEnabled(Context context,boolean enabled)throws Exception{mutate(context,null,c->c.put(ENABLED,enabled));}
 private static JSONObject copy(JSONObject value)throws Exception{return value==null?new JSONObject():new JSONObject(value.toString());}
 private static JSONArray array(JSONObject c,String key)throws Exception{JSONArray rows=c.optJSONArray(key);if(rows==null){rows=new JSONArray();c.put(key,rows);}return rows;}
 private static void check()throws InterruptedIOException{if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Background delivery stopped");}
 private static void ensureCurrent(Context context,JSONObject expected)throws Exception{synchronized(Vault.class){JSONObject latest=new Vault(context).read().getJSONObject("couple");if(!same(expected,latest)||!latest.optBoolean(ENABLED,false))throw new InterruptedIOException("Background delivery stopped");}}
 private static void validatePayload(JSONObject projection,JSONObject payload,String sender)throws Exception{if("signal".equals(payload.optString("kind")))payload.getJSONObject("signal");else if("sharedRecord".equals(payload.optString("kind")))SharedCoupleRecords.apply(projection,payload,sender);else CoupleProposal.apply(projection,payload,sender);}
 public static int pendingNotifications(Context context)throws Exception{JSONObject c=new Vault(context).read().optJSONObject("couple");return c==null||!c.optBoolean(ENABLED,false)||c.optString("pairId").isEmpty()||c.optJSONObject("peer")==null?0:c.optInt("backgroundNotificationPending",0);}
 public static void notificationDelivered(Context context,int count)throws Exception{mutate(context,null,c->c.put("backgroundNotificationPending",Math.max(0,c.optInt("backgroundNotificationPending",0)-count)));}
 private static boolean same(JSONObject a,JSONObject b){JSONObject ap=a.optJSONObject("peer"),bp=b.optJSONObject("peer");return a.optString("id").equals(b.optString("id"))&&a.optString("privateKey").equals(b.optString("privateKey"))&&a.optString("publicKey").equals(b.optString("publicKey"))&&a.optString("token").equals(b.optString("token"))&&a.optString("pairId").equals(b.optString("pairId"))&&ap!=null&&bp!=null&&ap.optString("id").equals(bp.optString("id"))&&ap.optString("publicKey").equals(bp.optString("publicKey"));}
 private static void mutate(Context context,JSONObject expected,Mutation mutation)throws Exception{synchronized(Vault.class){Vault vault=new Vault(context);JSONObject root=vault.read(),c=copy(root.optJSONObject("couple"));if(expected!=null&&!same(expected,c))throw new SecurityException("连接状态已改变，后台传送已停止。");mutation.apply(c);c.put("revision",c.optLong("revision",0)+1);root.put("couple",c);vault.write(root);}}
 private static JSONObject authenticate(JSONObject c,JSONObject e)throws Exception{JSONObject peer=c.getJSONObject("peer");if(!peer.getString("id").equals(e.getString("senderId")))throw new SecurityException("收到未知发送方，消息未被确认。");String plain=CoupleCrypto.decrypt(c.getString("privateKey"),peer.getString("publicKey"),c.getString("pairId"),e.getString("senderId"),e.getString("type"),e.getString("id"),e.getString("nonce"),e.getString("ciphertext"));JSONObject p=new JSONObject(plain);if(!e.getString("type").equals(p.optString("kind")))throw new SecurityException("消息类型校验失败，消息未被确认。");return p;}
 private static boolean known(JSONObject c,JSONObject e,JSONObject payload)throws Exception{JSONArray inbox=c.optJSONArray("inbox");if(inbox!=null)for(int i=0;i<inbox.length();i++){JSONObject row=inbox.getJSONObject(i);if(e.getString("id").equals(row.optString("id"))){if(!e.getString("senderId").equals(row.optString("sender"))||!payload.toString().equals(row.getJSONObject("payload").toString()))throw new SecurityException("重复消息内容不一致。");return true;}}JSONArray spool=c.optJSONArray(SPOOL);if(spool!=null)for(int i=0;i<spool.length();i++){JSONObject row=spool.getJSONObject(i);if(!belongs(c,row))continue;JSONObject prior=row.getJSONObject("envelope");if(e.getString("id").equals(prior.optString("id"))){if(!payload.toString().equals(authenticate(c,prior).toString()))throw new SecurityException("重复消息内容不一致。");return true;}}return false;}
 private static boolean belongs(JSONObject c,JSONObject row){JSONObject peer=c.optJSONObject("peer");return peer!=null&&c.optString("pairId").equals(row.optString("pairId"))&&peer.optString("id").equals(row.optString("peerId"))&&peer.optString("publicKey").equals(row.optString("peerKey"));}
 public static int run(Context context,CoupleApi api)throws Exception{synchronized(LOCK){check();JSONObject c=copy(new Vault(context).read().optJSONObject("couple"));if(!c.optBoolean(ENABLED,false)||c.optString("token").isEmpty()||c.optString("pairId").isEmpty()||c.optJSONObject("peer")==null)return 0;
  JSONObject me=api.get("/me",c.getString("token")),remote=me.optJSONObject("peer"),pinned=c.getJSONObject("peer");check();if(!c.getString("id").equals(me.optString("id"))||!c.getString("publicKey").equals(me.optString("publicKey"))||remote==null||!pinned.getString("id").equals(remote.optString("id"))||!pinned.getString("publicKey").equals(remote.optString("publicKey"))||!c.getString("pairId").equals(me.optString("pairId"))){mutate(context,c,latest->{latest.put(ENABLED,false);latest.remove("backgroundNotificationPending");});throw new SecurityException("伴侣身份或连接密钥发生变化，后台通信已停止。");}
  JSONArray received=api.get("/messages",c.getString("token")).getJSONArray("messages"),ack=new JSONArray();int[] novel={0};check();
  mutate(context,c,latest->{if(!latest.optBoolean(ENABLED,false))throw new InterruptedIOException("Background delivery stopped");JSONObject projection=copy(latest);JSONArray staged=latest.optJSONArray(SPOOL);if(staged!=null)for(int k=0;k<staged.length();k++){JSONObject row=staged.getJSONObject(k);if(belongs(latest,row))validatePayload(projection,authenticate(latest,row.getJSONObject("envelope")),row.getJSONObject("envelope").getString("senderId"));}JSONArray spool=array(latest,SPOOL);for(int i=0;i<received.length();i++){check();JSONObject e=received.getJSONObject(i),payload=authenticate(latest,e);if(!known(latest,e,payload)){validatePayload(projection,payload,e.getString("senderId"));if(spool.length()>=2000||spool.toString().length()+e.toString().length()>8*1024*1024)throw new IllegalStateException("后台收件空间已满，请打开爱人页。");spool.put(new JSONObject().put("pairId",latest.getString("pairId")).put("peerId",pinned.getString("id")).put("peerKey",pinned.getString("publicKey")).put("envelope",copy(e)));if(!"signal".equals(payload.optString("kind"))&&!("sharedRecord".equals(payload.optString("kind"))&&"received".equals(payload.optString("action"))))novel[0]++;}ack.put(e.getString("id"));}latest.put("backgroundNotificationPending",latest.optInt("backgroundNotificationPending",0)+novel[0]);});
  check();ensureCurrent(context,c);if(ack.length()>0)api.post("/messages/ack",c.getString("token"),new JSONObject().put("ids",ack));
  JSONArray out=CoupleDeliveryQueue.page(new Vault(context).read().getJSONObject("couple"),System.currentTimeMillis());if(CoupleDeliveryQueue.hasBulk(out))mutate(context,c,latest->latest.put("bulkNextSendAt",System.currentTimeMillis()+30000));if(out!=null)for(int i=0;i<out.length();i++){check();JSONObject envelope=out.getJSONObject(i);synchronized(Vault.class){JSONObject latest=new Vault(context).read().getJSONObject("couple");if(!same(c,latest)||!latest.optBoolean(ENABLED,false))throw new InterruptedIOException("Background delivery stopped");}api.post("/messages",c.getString("token"),CoupleDeliveryQueue.wire(envelope));mutate(context,c,latest->{JSONArray current=array(latest,"outbox");for(int j=current.length()-1;j>=0;j--)if(envelope.getString("id").equals(current.getJSONObject(j).optString("id")))current.remove(j);});}
  return novel[0];
 }}
 /** Foreground projection and receipts commit together; a failed projection keeps the whole spool. */
 public static void drain(Context context,Receiver receiver)throws Exception{synchronized(LOCK){JSONObject c=copy(new Vault(context).read().optJSONObject("couple"));JSONArray spool=c.optJSONArray(SPOOL);if(spool==null||spool.length()==0)return;mutate(context,c,latest->{JSONArray rows=array(latest,SPOOL);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(belongs(latest,row)){JSONObject envelope=row.getJSONObject("envelope");authenticate(latest,envelope);receiver.receive(latest,envelope);}}latest.remove(SPOOL);});}}
}


